mapper.update:
UPDATE biz_document_share_link
SET enabled = 0,
    revoked_at = COALESCE(revoked_at, CURRENT_TIMESTAMP(3)),
    update_time = CURRENT_TIMESTAMP(3)
WHERE id = #{id}
  AND creator_user_id = #{creatorUserId}

mapper.select:
SELECT share_link_id, user_id, permission, redeemed_at
FROM biz_document_share_link_redemption
WHERE share_link_id = #{shareLinkId}
  AND user_id = #{userId}
